import re

def parse(lines):
    flat = []
    fl = []
    ent = []
    el = []
    rel = []
    rl = []
    idx = []
    il = []
    samp = {}
    sl = []
    gran = {}
    gl = []
    skip = []
    sec = None
    cur = None
    pend = []
    flat_re = re.compile(r'^\s*(?P<pct>[\d.]+)\s+(?P<cum>[\d.]+)\s+(?P<self>[\d.]+)(?:\s+(?P<calls>\d+(?:\+\d+)?)\s+(?P<sms>[\d.]+)\s+(?P<tms>[\d.]+))?\s+(?P<name>[^\s\d\[].*?)\s*$')
    ent_re = re.compile(r'^\[(?P<index>\d+)\]\s+(?P<pct>[\d.]+)\s+(?P<self>[\d.]+)\s+(?P<children>[\d.]+)(?:\s+(?P<called>\d+(?:\+\d+)?))?\s+(?P<name>\S.*?)\s+\[(?P<ref>\d+)\]\s*$')
    rel_re = re.compile(r'^\s+(?:(?P<self>[\d.]+)\s+(?P<children>[\d.]+)\s+)?(?:(?P<called>\d+(?:\+\d+)?(?:/\d+)?)\s+)?(?P<name>\S.*?)(?:\s+\[(?P<ref>\d+)\])?\s*$')
    for i, l in enumerate(lines):
        s = l.strip()
        if not s:
            continue
        if re.match(r'^Flat profile:', s):
            sec = 'flat'
            skip.append(i)
            continue
        if re.match(r'^Call graph', s):
            sec = 'graph'
            skip.append(i)
            continue
        if re.match(r'^Index by function name', s):
            sec = 'index'
            skip.append(i)
            continue
        if re.match(r'^-{5,}$', s):
            cur = None
            pend = []
            skip.append(i)
            continue
        m = re.match(r'^Each sample counts as\s+([\d.]+ \S+?)\.?$', s)
        if m:
            samp['Each sample counts as'] = m.group(1)
            sl.append(i)
            continue
        m = re.match(r'^granularity:\s*(.+?)$', s)
        if m:
            gran['granularity'] = m.group(1)
            gl.append(i)
            continue
        if sec == 'flat':
            if re.match(r'^%\s+cumulative\s+self|^time\s+seconds\s+seconds', s):
                fl.append(i)
                continue
            m = flat_re.match(l)
            if m:
                flat.append({'% time': m.group('pct'), 'cumulative seconds': m.group('cum'), 'self seconds': m.group('self'), 'calls': m.group('calls') or '', 'self ms/call': m.group('sms') or '', 'total ms/call': m.group('tms') or '', 'name': m.group('name')})
                fl.append(i)
        elif sec == 'graph':
            if re.match(r'^index\s+% time\s+self\s+children', s):
                el.append(i)
                continue
            m = ent_re.match(l)
            if m:
                cur = m.group('index')
                for r in pend:
                    r['entry'] = cur
                pend = []
                ent.append({'index': cur, '% time': m.group('pct'), 'self': m.group('self'), 'children': m.group('children'), 'called': m.group('called') or '', 'name': m.group('name'), 'ref': m.group('ref')})
                el.append(i)
                continue
            m = rel_re.match(l)
            if m:
                r = {'entry': cur or '', 'role': 'child' if cur else 'parent', 'self': m.group('self') or '', 'children': m.group('children') or '', 'called': m.group('called') or '', 'name': m.group('name'), 'ref': m.group('ref') or ''}
                if not cur:
                    pend.append(r)
                rel.append(r)
                rl.append(i)
        elif sec == 'index':
            found = False
            for m in re.finditer(r'\[(\d+)\]\s+(.*?)(?=\s+\[\d+\]|\s*$)', l):
                idx.append({'index': m.group(1), 'name': m.group(2)})
                found = True
            if found:
                il.append(i)
    blocks = []
    if samp:
        blocks.append({'name': 'sampling', 'kind': 'kv', 'lines': sl, 'records': [samp]})
    if gran:
        blocks.append({'name': 'granularity', 'kind': 'kv', 'lines': gl, 'records': [gran]})
    if fl:
        blocks.append({'name': 'flat_profile', 'kind': 'table', 'lines': fl, 'records': flat})
    if el:
        blocks.append({'name': 'call_graph_entries', 'kind': 'table', 'lines': el, 'records': ent})
    if rl:
        blocks.append({'name': 'call_graph_relatives', 'kind': 'table', 'lines': rl, 'records': rel})
    if il:
        blocks.append({'name': 'function_index', 'kind': 'table', 'lines': il, 'records': idx})
    return {'blocks': blocks, 'skip': skip}
